function topo(n, edges){ var indeg=new Array(n).fill(0); var adj=[]; for(var i=0;i<n;i++) adj.push([]);
  for(var e=0;e<edges.length;e++){ var u=edges[e][0],v=edges[e][1]; adj[u].push(v); indeg[v]++; }
  var q=[]; for(var i=0;i<n;i++) if(indeg[i]===0) q.push(i);
  var order=[];
  while(q.length){ var u=q.shift(); order.push(u);
    for(var j=0;j<adj[u].length;j++){ var v=adj[u][j]; if(--indeg[v]===0) q.push(v); } }
  if(order.length!==n) return {order:null, hasCycle:true};
  return {order:order, hasCycle:false};
}
var EXPORTS={topo:topo};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TopoSortForgePure = EXPORTS; }
